{
  "findings": [
    {
      "check_id": "CKV_GCP_68",
      "title": "Google Storage Bucket should have encryption enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "HIGH",
      "explanation": "The bucket does not specify a customer-managed encryption key (CMEK) or default encryption. Without encryption, sensitive data stored in the bucket may be exposed if accessed improperly."
    },
    {
      "check_id": "CKV_GCP_28",
      "title": "Google Storage Bucket should have logging enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Logging is not enabled for the bucket. Without logging, it is difficult to track access and changes to the bucket, which can hinder incident response and auditing."
    }
  ],
  "patched_code": "resource "google_storage_bucket" "compliance_storage" {
  name     = "${var.project_id}-digital-asset-trading-platform-compliance"
  location = var.region

  versioning {
    enabled = true
  }

  encryption {
    default_kms_key_name = var.kms_key_name
  }

  logging {
    log_bucket        = var.log_bucket
    log_object_prefix = "${var.project_id}-compliance-logs"
  }

  lifecycle_rule {
    condition {
      age = 2555
    }
    action {
      type = "Delete"
    }
  }
}",
  "fix_summary": "Added encryption block to enable default encryption using a customer-managed key (CMEK). Added logging block to enable bucket access logging for auditing purposes."
}
